import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Skills, Skillcap & Teachers","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/characters/skills.md","filePath":"en/guide/characters/skills.md"}'),s={name:"en/guide/characters/skills.md"};function l(n,e,o,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="skills-skillcap-teachers" tabindex="-1">Skills, Skillcap &amp; Teachers <a class="header-anchor" href="#skills-skillcap-teachers" aria-label="Permalink to &quot;Skills, Skillcap &amp; Teachers&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Availability not established.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li><a href="/Syrolands-Public/en/guide/glossary.html#skill">Skills</a> share a proposed budget of about 700 points, with 100 as the normal maximum per skill.</li><li>Learn unfamiliar fundamentals from a teacher; then develop through meaningful use.</li><li>Deep expertise should matter without making beginners ineffective.</li></ul><p><span id="capability-within-a-shared-budget"></span><span id="useful-at-every-stage"></span><span id="learning-skills-and-finding-teachers"></span><span id="know-what-training-offers"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Player meaning</th></tr></thead><tbody><tr><td>Start a discipline</td><td>A teacher, academy, guild or specialist generally supplies missing fundamentals. Backgrounds can already include them.</td></tr><tr><td>Practice</td><td>Early progress should be accessible; advanced expertise takes sustained effort.</td></tr><tr><td>Choose investment</td><td>Primary specialties compete with useful support skills for the same budget.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Skill caps encourage choosing what to train.</td><td>Retain that choice, with no universal expectation of a seven-GM build.</td></tr><tr><td>Later UO supports skill-cap increases through Power Scrolls.</td><td>Ordinary progression beyond 100 is not planned.</td></tr></tbody></table><p>UO rules vary by era and shard. <a href="https://uo.com/wiki/ultima-online-wiki/items/scrolls-of-power/" target="_blank" rel="noreferrer">Official UO: Scrolls of Power</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>An archer could invest deeply in Archery while taking enough Tailoring for useful field work. That supporting investment should contribute without replacing an expert tailor.</p><h2 id="progression-trade-offs" tabindex="-1">Progression / trade-offs <a class="header-anchor" href="#progression-trade-offs" aria-label="Permalink to &quot;Progression / trade-offs&quot;">​</a></h2><p>Exact caps, gain rates, teaching costs and teacher availability remain open. Clear next steps should explain capabilities without revealing every hidden <a href="/Syrolands-Public/en/guide/characters/techniques.html">technique</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/characters/progression.html">Progression</a> · <a href="/Syrolands-Public/en/guide/characters/techniques.html">Techniques</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p>Read the <a href="/Syrolands-Public/en/game-design/characters/skills-and-skillcap.html">Skills, Skillcap &amp; Teachers</a> design specification.</p>',18)])])}const f=a(s,[["render",l]]);export{u as __pageData,f as default};
